<?php
namespace App\Http\Controllers\Dashboard; use App\Http\Controllers\Controller; use App\Http\Requests\StorePropertyRequest; use App\Models\Currency; use App\Models\Property; use App\Modules\Property\Application\Actions\CreatePropertyAction; use App\Modules\Property\Application\Actions\SubmitPropertyAction;
class PropertyController extends Controller {public function index(){return view('dashboard.properties.index',['properties'=>Property::with('translations')->where('owner_id',auth()->id())->latest()->paginate(20)]);} public function create(){return view('dashboard.properties.create',['currencies'=>Currency::where('is_active',true)->get()]);} public function store(StorePropertyRequest $request,CreatePropertyAction $action){$p=$action->execute($request->validated(),$request->user()->id);return redirect()->route('dashboard.properties.index',['locale'=>app()->getLocale()])->with('success','Draft created: '.$p->reference_code);} public function submit(string $locale,Property $property,SubmitPropertyAction $action){$this->authorize('update',$property);$action->execute($property);return back()->with('success','Submitted for review.');}}
